const {createHash}=require('node:crypto');
const fail=(message,status=400)=>{throw Object.assign(new Error(message),{status});};
// Codes are bearer secrets generated by the issuing client. Only hashes are stored.
function createSkinPromoService(store,{now=Date.now,enabled=()=>process.env.SKIN_PROMO_CODES_ENABLED==='1'&&process.env.SKIN_SYSTEM_ENABLED==='true'}={}) {
  const db=store.db;
  db.exec(`CREATE TABLE IF NOT EXISTS economy_skin_promos (
    code_hash TEXT PRIMARY KEY,preset_id TEXT NOT NULL,actor TEXT NOT NULL,
    fingerprint TEXT NOT NULL,reason TEXT NOT NULL,expires_at INTEGER NOT NULL,
    request_id TEXT UNIQUE NOT NULL,created_at INTEGER NOT NULL,
    redeemed_by TEXT,redeemed_at INTEGER,revoked_at INTEGER);
    CREATE TABLE IF NOT EXISTS economy_skin_promo_revocations (
    code_hash TEXT PRIMARY KEY,actor TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);`);
  const tx=fn=>{db.exec('BEGIN IMMEDIATE');try{const out=fn();db.exec('COMMIT');return out;}catch(e){db.exec('ROLLBACK');throw e;}};
  const gate=()=>{if(!enabled())fail('Promotional skin codes are not enabled',503);};
  const admin=user=>{const steam=store.validateSteamId(user?.steam_id);if(!user?.is_admin)fail('Admin access required',403);return steam;};
  const digest=code=>{if(typeof code!=='string'||!/^HVP-[a-f0-9]{64}$/.test(code))fail('Invalid promotional code');return createHash('sha256').update(code).digest('hex');};
  const fingerprint=p=>createHash('sha256').update(JSON.stringify([p.species,p.skin])).digest('hex');
  const reason=value=>{if(typeof value!=='string'||value.trim().length<10||value.length>500)fail('A reason of 10–500 characters is required');return value.trim();};
  const eligible=p=>{if(!p?.active||p.membershipPremium)fail('Choose an active skin outside the membership collection',409);};
  function issue(user,input={}) {
    gate();const actor=admin(user),hash=digest(input.code),why=reason(input.reason);
    if(typeof input.requestId!=='string'||!/^[\w-]{8,128}$/.test(input.requestId)||!Number.isSafeInteger(input.expiresAt))fail('A request ID and expiry are required');
    return tx(()=>{
      const old=db.prepare('SELECT * FROM economy_skin_promos WHERE request_id=? OR code_hash=?').get(input.requestId,hash);
      if(old){if(old.request_id!==input.requestId||old.code_hash!==hash||old.actor!==actor||old.preset_id!==input.presetId||old.reason!==why||old.expires_at!==input.expiresAt)fail('Conflicting code issuance request',409);return {duplicate:true,id:hash};}
      if(input.expiresAt<=now()||input.expiresAt>now()+90*86400000)fail('Expiry must be within the next 90 days');
      const preset=store.getSkinPreset(input.presetId);eligible(preset);
      if(preset.owner_steam_id!==actor)fail('Only the creator can issue promotional codes for this skin',403);
      db.prepare('INSERT INTO economy_skin_promos(code_hash,preset_id,actor,fingerprint,reason,expires_at,request_id,created_at) VALUES (?,?,?,?,?,?,?,?)')
        .run(hash,preset.id,actor,fingerprint(preset),why,input.expiresAt,input.requestId,now());
      return {duplicate:false,id:hash};
    });
  }
  function redeem(user,{code}={}) {
    gate();const steam=store.validateSteamId(user?.steam_id),hash=digest(code);
    return tx(()=>{
      const row=db.prepare('SELECT * FROM economy_skin_promos WHERE code_hash=?').get(hash);
      if(!row)fail('This code is unavailable',404);
      if(row.redeemed_by===steam)return {duplicate:true,presetId:row.preset_id};
      if(row.redeemed_by||row.revoked_at!==null||row.expires_at<=now())fail('This code is unavailable',409);
      const preset=store.getSkinPreset(row.preset_id);eligible(preset);
      if(preset.owner_steam_id!==row.actor||fingerprint(preset)!==row.fingerprint)fail('The skin changed after this code was issued',409);
      if(preset.owner_steam_id===steam||store.hasSkinUnlock(steam,preset.id))return {alreadyOwned:true,presetId:preset.id};
      store.ensureWallet(steam);
      db.prepare('INSERT INTO economy_skin_unlocks(steam_id,preset_id,purchase_price,idempotency_key) VALUES (?,?,0,?)').run(steam,preset.id,`skin-promo:${hash}`);
      db.prepare('UPDATE economy_skin_promos SET redeemed_by=?,redeemed_at=? WHERE code_hash=?').run(steam,now(),hash);
      return {duplicate:false,presetId:preset.id};
    });
  }
  function revoke(user,{id,reason:inputReason}={}) {
    gate();const actor=admin(user),why=reason(inputReason);
    return tx(()=>{
      const row=db.prepare('SELECT * FROM economy_skin_promos WHERE code_hash=?').get(id);
      if(!row||row.actor!==actor)fail('Promotional code not found',404);
      const old=db.prepare('SELECT * FROM economy_skin_promo_revocations WHERE code_hash=?').get(id);
      if(old){if(old.reason!==why||old.actor!==actor)fail('Conflicting revocation',409);return {duplicate:true};}
      if(row.redeemed_by)fail('A redeemed code cannot be revoked',409);
      db.prepare('UPDATE economy_skin_promos SET revoked_at=? WHERE code_hash=?').run(now(),id);
      db.prepare('INSERT INTO economy_skin_promo_revocations VALUES (?,?,?,?)').run(id,actor,why,now());
      return {duplicate:false};
    });
  }
  function list(user) {
    gate();const actor=admin(user);
    return {codes:db.prepare('SELECT code_hash AS id,preset_id AS presetId,(SELECT name FROM economy_skin_presets WHERE id=economy_skin_promos.preset_id) AS name,reason,created_at AS createdAt,expires_at AS expiresAt,redeemed_at AS redeemedAt,revoked_at AS revokedAt FROM economy_skin_promos WHERE actor=? ORDER BY created_at DESC,rowid DESC LIMIT 100').all(actor)};
  }
  return {issue,redeem,revoke,list};
}
module.exports={createSkinPromoService};
